-- TESTING only. Existing actor; every fixture, grant, assignment, movement and Audit row rolls back.
begin;
create function pg_temp.lean_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'Lean invariant failed: %',label;end if;end$$;
create function pg_temp.lean_error(sql text,wanted text) returns void language plpgsql as $$begin
 begin execute sql;exception when others then if sqlerrm=wanted then return;end if;raise exception 'wanted %, got %',wanted,sqlerrm;end;
 raise exception 'expected %',wanted;
end$$;
create temp table lean_qa_fixture(factory_id uuid,actor_id uuid,technician_id uuid,product_id uuid,line_id uuid,machine_id uuid,item_id uuid,cause_id uuid,problem_id uuid,initiative_id uuid);
do $test$
declare f uuid;actor uuid;tech uuid;product uuid;line uuid;machine uuid;item uuid;request uuid;entry uuid;startup uuid:=gen_random_uuid();cause uuid;other_cause uuid;
 payload jsonb;recording jsonb;review uuid:=gen_random_uuid();problem uuid;initiative uuid:=gen_random_uuid();a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();result jsonb;retry uuid:=gen_random_uuid();at_time timestamptz; evidence jsonb;rev integer;comparison uuid:=gen_random_uuid();
begin
 select m.factory_id,m.user_id,m.id into f,actor,tech from public.memberships m join public.factories fac on fac.id=m.factory_id where fac.is_demo and m.status='approved' and exists(select 1 from public.user_permissions where factory_id=m.factory_id and user_id=m.user_id and module='orders' and action='edit') limit 1;
 if f is null then raise exception 'existing TESTING actor required';end if;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 insert into public.user_permissions(factory_id,user_id,module,action) select f,actor,module,action from public.permissions where module in ('lean','lean_standards') on conflict do nothing;
 update public.production_shifts set archived=true where factory_id=f;
 select id into cause from public.downtime_reasons where factory_id=f and name='Cooling water level low';
 select id into other_cause from public.downtime_reasons where factory_id=f and name='Other';
 insert into public.products(factory_id,name,code,unit,stock_unit,unit_weight_kg) values(f,'Lean rollback pipe','LEAN-'||substr(gen_random_uuid()::text,1,8),'piece','piece',2) returning id into product;
 insert into public.production_lines(factory_id,name,code) values(f,'Lean rollback line','LEAN-'||substr(gen_random_uuid()::text,1,8)) returning id into line;
 insert into public.work_centers(factory_id,name,code,line_id,category_id) select f,'Lean rollback machine','LEAN-'||substr(gen_random_uuid()::text,1,8),line,category_id from public.work_centers where factory_id=f and category_id is not null limit 1 returning id into machine;
 insert into public.work_center_capabilities(factory_id,work_center_id,product_id,rate,rate_unit) values(f,machine,product,100,'piece');
 request:=public.create_production_request(f,'Lean rollback request','normal',null,'Lean verification fixture',jsonb_build_array(jsonb_build_object('product_id',product,'quantity',1000,'unit','piece')));
 select id into item from public.production_orders where request_id=request;
 update public.production_orders set line_id=line,start_time=now()-interval '2 hours',expected_finish=now()-interval '1 hour' where id=item;
 perform public.start_product_item(f,item);
 perform public.lean_command(f,gen_random_uuid(),'standard',jsonb_build_object('id',gen_random_uuid(),'line_id',line,'product_id',product,'running_percent',5,'startup_kg',20,'expected_revision',0));
 select actual_start into at_time from public.production_orders where id=item;
 payload:=jsonb_build_object('unit_kind','line','production_unit',line,'item',item,'technician',tech,'good',100,'discarded_quantity',0,'scrap_kg',30,'startup_kg',20,'startup_id',startup,'startup_at',at_time,'unfinished',20,'remaining_work','Printing and cutting','input_quantity',0);
 recording:=public.record_lean_production(f,payload,retry);entry:=(recording->>'id')::uuid;
 perform pg_temp.lean_assert((recording->>'produced_kg')::numeric=240,'Good + new WIP mass, never discarded quantity');
 perform pg_temp.lean_assert(not (recording->>'needs_review')::boolean,'legitimate startup excluded from abnormal running rate');
 perform pg_temp.lean_assert(not exists(select 1 from private.lean_occurrences where factory_id=f and product_id=product),'normal startup creates no problem');
 perform pg_temp.lean_assert((public.record_lean_production(f,payload,retry)->>'id')::uuid=entry,'recording retry exactly once');
 perform pg_temp.lean_assert((select good_quantity=100 from public.production_orders where id=item),'WIP/Scrap never satisfy Good');
 perform pg_temp.lean_assert((select count(*)=1 from public.finished_goods_movements where entry_id=entry and stock_delta=100),'Good credits inventory exactly once');
 recording:=public.record_lean_production(f,payload||jsonb_build_object('good',0,'unfinished',0,'scrap_kg',5,'startup_kg',5),gen_random_uuid());
 perform pg_temp.lean_assert((recording->>'needs_review')::boolean,'same startup allowance consumed once and excess prompts review');
 entry:=(recording->>'id')::uuid;
 perform public.lean_command(f,gen_random_uuid(),'scrap_observation',jsonb_build_object('id',review,'entry_id',entry,'occurred_at',at_time,'preliminary_cause_id',other_cause,'observation','Water level fell','response','Restored cooling water'));
 perform public.lean_command(f,gen_random_uuid(),'scrap_review',jsonb_build_object('id',review,'approved_cause_id',cause,'note','Confirmed cooling cause','expected_revision',1));
 perform pg_temp.lean_assert((select observation='Water level fell' and preliminary_cause_id=other_cause and approved_cause_id=cause from public.lean_scrap_events where id=review),'original explanation preserved separately');
 perform pg_temp.lean_assert((select count(*)=1 from private.lean_occurrences where factory_id=f and mechanism='scrap' and product_id=product),'high scrap without downtime');
 result:=public.lean_command(f,gen_random_uuid(),'problem',jsonb_build_object('mechanism','scrap','line_id',line,'product_id',product,'cause_id',cause,'expected_revision',0,'monitor_only',true));problem:=(result->>'id')::uuid;
 perform pg_temp.lean_assert((public.lean_read(f,jsonb_build_object('mode','problems','product_id',product,'to',clock_timestamp()))->>'total')::int=1,'Monitor Only remains visible, no automatic initiative');
 perform pg_temp.lean_assert(not exists(select 1 from public.lean_initiatives where factory_id=f and problem_id=problem),'no automatic initiative');
 perform public.lean_command(f,gen_random_uuid(),'initiative',jsonb_build_object('id',initiative,'problem_id',problem,'product_id',product,'title','Restore stable cooling'));
 perform pg_temp.lean_error(format('select public.lean_command(%L,gen_random_uuid(),%L,%L::jsonb)',f,'action',jsonb_build_object('id',a,'initiative_id',initiative,'title','Repair water supply','action_type','MAINTENANCE','owner_id',actor)),'lean_invalid');
 perform public.lean_command(f,gen_random_uuid(),'action',jsonb_build_object('id',a,'initiative_id',initiative,'title','Repair water supply','action_type','MAINTENANCE','owner_id',actor,'due_date',current_date+7));
 perform public.lean_command(f,gen_random_uuid(),'action',jsonb_build_object('id',b,'initiative_id',initiative,'title','Improve startup procedure','action_type','PROCESS','owner_id',actor,'due_date',current_date+14));
 perform public.lean_command(f,gen_random_uuid(),'progress',jsonb_build_object('id',a,'status','COMPLETED','due_date',current_date+8,'note','Repair finished','expected_revision',1));
 perform pg_temp.lean_assert((select completed_at is null from public.lean_initiatives where id=initiative),'incomplete second action blocks verification');
 perform public.lean_command(f,gen_random_uuid(),'cancel_action',jsonb_build_object('id',b,'reason','Procedure already replaced','expected_revision',1));
 perform pg_temp.lean_assert((select completed_at is not null and verified_at is null from public.lean_initiatives where id=initiative),'all completed/removed => Awaiting Verification only');
 perform pg_temp.lean_assert((select status='CANCELLED' and cancellation_reason='Procedure already replaced' from public.lean_actions where id=b),'cancelled history survives');
 perform pg_temp.lean_assert((select startup_kg=20 from public.lean_standards where factory_id=f and line_id=line and product_id=product),'observed 25 kg does not change approved 20 kg');
 evidence:=jsonb_build_object('product_id',product,'problem_id',problem,'runtime_hours',null,'coverage_complete',false,'source_revision',(select revision from private.lean_source_state where factory_id=f));
 perform set_config('request.jwt.claim.role','service_role',true);
 select revision into rev from public.lean_initiatives where id=initiative;
 perform public.store_lean_evidence(f,actor,'baseline',initiative,rev,evidence,'{}',gen_random_uuid());
 select revision into rev from public.lean_initiatives where id=initiative;
 perform pg_temp.lean_error(format('select public.store_lean_evidence(%L,%L,%L,%L,%s,%L::jsonb,%L::jsonb,gen_random_uuid())',f,actor,'verify',initiative,rev,evidence||jsonb_build_object('complete',false),jsonb_build_object('outcome','IMPROVED','note','Human confirmation')),'lean_insufficient_exposure');
 perform public.store_lean_evidence(f,actor,'save_comparison',problem,0,evidence,jsonb_build_object('cutoff',at_time,'desired_hours',40),comparison);
 perform pg_temp.lean_assert((select verified_at is null and revision=rev from public.lean_initiatives where id=initiative),'manual saved comparison leaves official state unchanged');
 perform public.store_lean_evidence(f,actor,'verify',initiative,rev,evidence||jsonb_build_object('complete',false),jsonb_build_object('outcome','INSUFFICIENT_DATA','note','Historical runtime unavailable'),gen_random_uuid());
 perform pg_temp.lean_assert((select outcome='INSUFFICIENT_DATA' and verified_by=actor and verified_at is not null from public.lean_initiatives where id=initiative),'whole initiative closes only after human verification');
 perform set_config('request.jwt.claim.role','authenticated',true);
 delete from public.user_permissions where factory_id=f and user_id=actor and module='lean' and action='edit';
 perform pg_temp.lean_error(format('select public.lean_command(%L,gen_random_uuid(),%L,%L::jsonb)',f,'cancel_action',jsonb_build_object('id',a,'expected_revision',2,'reason','Owner cannot remove')),'permission_denied');
 perform public.lean_command(f,gen_random_uuid(),'problem',jsonb_build_object('mechanism','scrap','line_id',line,'product_id',product,'cause_id',other_cause,'expected_revision',0));
 perform pg_temp.lean_assert(exists(select 1 from public.lean_problem_settings where factory_id=f and product_id=product and cause_id=other_cause and not monitor_only and threshold_percent=10),'create-only caller can materialize a default identity');
 perform pg_temp.lean_error(format('select public.lean_command(%L,gen_random_uuid(),%L,%L::jsonb)',f,'problem',jsonb_build_object('mechanism','scrap','line_id',line,'product_id',product,'cause_id',other_cause,'expected_revision',0,'monitor_only',true)),'permission_denied');
 perform pg_temp.lean_assert(not has_function_privilege('authenticated','public.store_lean_evidence(uuid,uuid,text,uuid,integer,jsonb,jsonb,uuid)','execute'),'browser cannot forge evidence');
 perform pg_temp.lean_assert(not has_function_privilege('authenticated','public.record_production(uuid,text,uuid,uuid,uuid,numeric,numeric,text,boolean,uuid,uuid,text,numeric,text,uuid,numeric)','execute'),'all old mixed-unit overloads revoked');
 perform pg_temp.lean_assert(not has_table_privilege('authenticated','public.lean_actions','update'),'protected transitions at database boundary');
 perform pg_temp.lean_assert(exists(select 1 from public.audit_logs where factory_id=f and entity_id=b and new_data->>'status'='CANCELLED'),'reasoned cancellation audited');
 insert into lean_qa_fixture values(f,actor,tech,product,line,machine,item,cause,problem,initiative);
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 perform pg_temp.lean_error(format('select public.lean_read(%L,%L)',f,'{}'),'permission_denied');
end$test$;
-- Retrospective rollback-only watch fixtures; no historical runtime or live verification is fabricated.
do $watch_and_link$
declare x record;r jsonb;stop uuid;review uuid:=gen_random_uuid();start_at timestamptz;entry_at timestamptz;other_machine uuid;watch_problem uuid;watch_initiative uuid:=gen_random_uuid();begin
 select * into x from lean_qa_fixture;perform set_config('request.jwt.claim.sub',x.actor_id::text,true);
 insert into public.user_permissions(factory_id,user_id,module,action) values(x.factory_id,x.actor_id,'lean','edit') on conflict do nothing;
 update public.work_centers set order_id=x.item_id where id=x.machine_id;
 insert into public.lean_problem_settings(factory_id,mechanism,machine_id,cause_id,created_by) values(x.factory_id,'downtime',x.machine_id,x.cause_id,x.actor_id) returning id into watch_problem;
 insert into public.lean_initiatives(id,factory_id,problem_id,product_id,title,baseline_from,baseline_to,created_by,completed_at,verified_at,verified_by,outcome,verification_note) values(watch_initiative,x.factory_id,watch_problem,x.product_id,'Retrospective recurrence fixture',now()-interval '20 minutes',now()-interval '10 minutes',x.actor_id,now()-interval '9 minutes',now()-interval '8 minutes',x.actor_id,'IMPROVED','Rollback-only recurrence fixture');
 for n in 1..2 loop
 insert into public.downtime_events(factory_id,work_center_id,started_at,ended_at,reason_id,created_by,approved_cause_id,approved_by,approved_at,retroactive) values(x.factory_id,x.machine_id,now()-n*interval '2 minutes',now()-n*interval '2 minutes'+interval '1 minute',x.cause_id,x.actor_id,x.cause_id,x.actor_id,now(),true);
 end loop;
 r:=public.lean_read(x.factory_id,jsonb_build_object('mode','detail','problem_id',watch_problem,'from',now()-interval '2 days','to',now()-interval '1 day'));
 perform pg_temp.lean_assert((r->>'total')::integer=0 and (r->'recurrence_watch'->>'frequency')::integer=2 and (r->'recurrence_watch'->>'recurred')::boolean,'recurrence watch uses all identity events independently of selected period');
 start_at:=clock_timestamp();
 r:=public.record_lean_production(x.factory_id,jsonb_build_object('unit_kind','line','production_unit',x.line_id,'item',x.item_id,'technician',x.technician_id,'good',10,'discarded_quantity',0,'scrap_kg',10,'startup_kg',0,'unfinished',0,'input_quantity',0),gen_random_uuid());
 select created_at into entry_at from public.production_entries where id=(r->>'id')::uuid;
 update public.work_centers set order_id=x.item_id where id=x.machine_id;
 insert into public.downtime_events(factory_id,work_center_id,line_id,order_id,started_at,ended_at,reason_id,created_by,approved_cause_id,approved_by,approved_at)
 values(x.factory_id,x.machine_id,x.line_id,x.item_id,start_at,clock_timestamp(),x.cause_id,x.actor_id,x.cause_id,x.actor_id,clock_timestamp()) returning id into stop;
 perform public.lean_command(x.factory_id,gen_random_uuid(),'scrap_observation',jsonb_build_object('id',review,'entry_id',r->>'id','occurred_at',entry_at,'preliminary_cause_id',x.cause_id,'observation','Linked physical cooling stop','response','Restored water','downtime_id',stop));
 perform public.lean_command(x.factory_id,gen_random_uuid(),'scrap_review',jsonb_build_object('id',review,'approved_cause_id',x.cause_id,'note','Reviewed same physical event','expected_revision',1));
 perform pg_temp.lean_assert((select count(*)=1 and sum(scrap_kg)=10 from private.lean_occurrences where factory_id=x.factory_id and event_id=stop),'same downtime plus scrap produces one occurrence with associated kg');
 perform pg_temp.lean_assert(not exists(select 1 from private.lean_occurrences where factory_id=x.factory_id and event_id=review),'linked scrap does not create a second independent problem');
 insert into public.work_centers(factory_id,name,code,category_id,line_id,order_id) select x.factory_id,'Second Lean fixture machine','LEAN2-'||substr(gen_random_uuid()::text,1,8),category_id,x.line_id,x.item_id from public.work_centers where id=x.machine_id returning id into other_machine;
 insert into public.downtime_events(factory_id,work_center_id,started_at,ended_at,reason_id,created_by,approved_cause_id,approved_by,approved_at) values(x.factory_id,other_machine,start_at,clock_timestamp(),x.cause_id,x.actor_id,x.cause_id,x.actor_id,clock_timestamp());
 perform pg_temp.lean_assert((select count(distinct machine_id)=2 from private.lean_occurrences where factory_id=x.factory_id and product_id=x.product_id and mechanism='downtime' and cause_id=x.cause_id),'same cause on two machines remains two identities');
end$watch_and_link$;
set constraints all immediate;
rollback;
